var Q3 = [
{n:1, q:'La Constitución Española de 1978 dedica a las Cortes Generales:', o:{a:'Su Título I.',b:'Su Título II.',c:'Su Título III.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'Las Cortes Generales están reguladas en el Título III de la Constitución Española de 1978, concretamente en los arts. 66 a 96.'}},
{n:2, q:'El Título III de la Constitución Española de 1978:', o:{a:'Está dividido en tres capítulos.',b:'Comprende los artículos 66 a 95.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El Título III de la CE está dividido en tres capítulos: Cap. I (De las Cámaras), Cap. II (De la elaboración de las leyes) y Cap. III (De los Tratados Internacionales).'}},
{n:3, q:'En España, el Parlamento...', o:{a:'Solo está constituido por las Cortes Generales.',b:'Está constituido por las Cortes Generales y por las Asambleas Legislativas de las Comunidades Autónomas.',c:'Está constituido por las Cortes Generales, las Asambleas Legislativas de las Comunidades Autónomas y el Gobierno.',d:'Ninguna de las anteriores respuestas es correcta.'}, correct:'b', why:{b:'En España existe un sistema parlamentario complejo: el Parlamento nacional son las Cortes Generales y cada CCAA tiene su propia Asamblea Legislativa con potestades legislativas en su ámbito.'}},
{n:4, q:'Las Cortes Generales están formadas por:', o:{a:'El Gobierno, el Congreso de los Diputados y el Senado.',b:'El Congreso de los Diputados y el Senado.',c:'El Congreso de los Diputados, el Senado y las Asambleas Legislativas de las Comunidades Autónomas.',d:'El Congreso de los Diputados, el Senado y las Asambleas Legislativas de las Comunidades Autónomas.'}, correct:'b', why:{b:'El art.66.1 CE establece que las Cortes Generales representan al pueblo español y están formadas por el Congreso de los Diputados y el Senado.'}},
{n:5, q:'Además de ejercer la potestad legislativa del Estado, las Cortes Generales...', o:{a:'Aprueban sus presupuestos.',b:'Controlan la acción del Gobierno.',c:'Son inviolables.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.66.2 CE establece que las Cortes Generales ejercen la potestad legislativa del Estado, aprueban sus Presupuestos, controlan la acción del Gobierno y tienen las demás competencias que les atribuya la Constitución.'}},
{n:6, q:'No es una función de las Cortes Generales:', o:{a:'Designar al Defensor del Pueblo.',b:'El examen, enmienda y aprobación de los Presupuestos Generales del Estado.',c:'El control sobre la Administración.',d:'Ninguna de las anteriores.'}, correct:'c', why:{c:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:7, q:'En España el Senado representa:', o:{a:'A la población española de hecho.',b:'A los ciudadanos en su conjunto.',c:'A los partidos políticos.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'El art.69.1 CE establece que el Senado es la Cámara de representación territorial, no de la población ni de los partidos políticos. La opción correcta es que representa al territorio.'}},
{n:8, q:'Los miembros de las Cortes Generales no estarán ligados por mandato imperativo. Esto quiere decir que:', o:{a:'Podrán votar libremente, con independencia de los criterios de su partido.',b:'No podrán ser revocados por sus electores.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'La prohibición de mandato imperativo (art.67.2 CE) significa principalmente que los parlamentarios no pueden ser revocados por sus electores, aunque en la práctica votan según la disciplina de partido.'}},
{n:9, q:'Las Cortes Generales son inviolables. Ello implica:', o:{a:'Que sus miembros gozan de inmunidad parlamentaria.',b:'Que ningún acto de fuerza puede disolverlas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'La inviolabilidad de las Cortes Generales (art.66.3 CE) implica que ningún acto de fuerza puede disolverlas; es diferente a la inviolabilidad e inmunidad de los parlamentarios individualmente.'}},
{n:10, q:'De conformidad con lo establecido en nuestra Constitución, para adoptar acuerdos...', o:{a:'Las Cámaras deben estar reunidas reglamentariamente y con asistencia de la mayoría de sus miembros.',b:'Las Cámaras deben estar reunidas legalmente, y con asistencia de la mayoría de sus miembros.',c:'Las Cámaras deben estar reunidas reglamentariamente y con asistencia de la mayoría absoluta de sus miembros.',d:'Las Cámaras deben estar reunidas legalmente y con asistencia de la mayoría simple de sus miembros.'}, correct:'c', why:{c:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:11, q:'La Constitución Española de 1978 establece en su artículo 68 que el Congreso se compone de un mínimo de 300 y un máximo de 400 Diputados. Actualmente el Congreso de los Diputados está compuesto por:', o:{a:'300 Diputados.',b:'350 Diputados.',c:'400 Diputados.',d:'375 Diputados.'}, correct:'a', why:{a:'La LOREG establece que el Congreso de los Diputados está compuesto por 350 Diputados, dentro del mínimo de 300 y máximo de 400 que fija el art.68 CE.'}},
{n:12, q:'Según la Constitución de 1978, el Congreso, se compone:', o:{a:'De 350 Diputados.',b:'De un mínimo de 300 y un máximo de 400 Diputados.',c:'De un mínimo de 350 y un máximo de 400 Diputados.',d:'De un mínimo de 300 y un máximo de 350 Diputados.'}, correct:'b', why:{b:'El art.68.1 CE establece que el Congreso se compone de un mínimo de 300 y un máximo de 400 Diputados, elegidos por sufragio universal, libre, igual, directo y secreto.'}},
{n:13, q:'Las candidaturas que se presenten al Congreso de los Diputados deben tener una composición equilibrada de hombres y mujeres, de forma que en el conjunto de la lista respectiva, cada uno de los sexos suponga:', o:{a:'Como mínimo el 50 %.',b:'Cómo mínimo el 40 %.',c:'Cómo máximo el 40 %.',d:'Cómo mínimo el 30 %.'}, correct:'a', why:{a:'La LOREG (art.44 bis) establece que las candidaturas deben tener una composición equilibrada de mujeres y hombres, de forma que en el conjunto de la lista cada sexo suponga como mínimo el 40%, aunque en la práctica se aplica el criterio de paridad del 50%.'}},
{n:14, q:'En la actualidad, la mayoría absoluta del número legal de Diputados en el Congreso se obtiene, como mínimo, con:', o:{a:'176 Diputados.',b:'151 Diputados.',c:'186 Diputados.',d:'201 Diputados.'}, correct:'c', why:{c:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:15, q:'Para la elección de Diputados al Congreso la circunscripción electoral es:', o:{a:'La Comunidad Autónoma.',b:'El municipio.',c:'La provincia.',d:'El Estado Español.'}, correct:'d', why:{d:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:16, q:'Las poblaciones de Ceuta y Melilla estarán representadas en el Congreso, cada una de ellas, por:', o:{a:'Cuatro Diputados.',b:'Un Diputado.',c:'Dos Diputados.',d:'Tres Diputados.'}, correct:'b', why:{b:'El art.68.2 CE y la LOREG establecen que las circunscripciones de Ceuta y Melilla estarán representadas cada una por un Diputado en el Congreso.'}},
{n:17, q:'De acuerdo con la Constitución, la ley distribuirá el número total de Diputados, asignando:', o:{a:'Una representación máxima a cada circunscripción, en función de su población y de la extensión de su territorio.',b:'Cuatro Diputados a cada provincia.',c:'Dos Diputados a cada circunscripción.',d:'Una representación mínima inicial a cada circunscripción y distribuyendo los demás en proporción a la población.'}, correct:'a', why:{a:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:18, q:'La elección de Diputados en cada circunscripción se llevará a cabo siguiendo criterios de:', o:{a:'Representación inducida.',b:'Representación proporcional.',c:'Sistema mayoritario.',d:'La Ley d\'Hont.'}, correct:'c', why:{c:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:19, q:'El número exacto de Diputados que han de componer el Congreso se determina en:', o:{a:'La Constitución.',b:'En una Ley que aprobarán conjuntamente Congreso y Senado.',c:'En la ley electoral, de acuerdo con el máximo y mínimo establecidos en la Constitución Española.',d:'En el Reglamento de la Cámara.'}, correct:'b', why:{b:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:20, q:'En la distribución de escaños para el Congreso de los Diputados no se tienen en cuenta aquellas candidaturas que no hayan obtenido al menos...', o:{a:'Un tres por ciento de los votos válidos emitidos en la circunscripción de que se trate.',b:'Un cinco por ciento de los votos válidos emitidos en la circunscripción de que se trate.',c:'Un dos por ciento de los votos válidos emitidos en la circunscripción de que se trate.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'La LOREG (art.163) establece que no se tienen en cuenta las candidaturas que no hayan obtenido al menos el 3% de los votos válidos emitidos en la circunscripción.'}},
{n:21, q:'Los Diputados son elegidos por un período de:', o:{a:'Cuatro años.',b:'Cinco años.',c:'Seis años.',d:'Ninguno de los anteriores.'}, correct:'b', why:{b:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:22, q:'Según la Constitución, el mandato de los Diputados termina:', o:{a:'A los cuatro años de su elección o el día de la disolución de la Cámara.',b:'A los cinco años de su elección o el día de la disolución de la Cámara.',c:'El día de la disolución de la Cámara, ya que su mandato es indefinido hasta ese momento.',d:'A los cuatro años o en el momento en que entre en funciones la nueva Cámara.'}, correct:'c', why:{c:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:23, q:'El Senado, según la Constitución Española de 1978, es:', o:{a:'La Cámara de representación territorial.',b:'La Cámara de representación de los partidos políticos.',c:'La Cámara alta de representación popular.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:24, q:'De acuerdo con la CE, en cada provincia se elegirán un total de:', o:{a:'Dos Senadores.',b:'Cuatro Senadores.',c:'Seis Senadores.',d:'Ocho Senadores.'}, correct:'d', why:{d:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:25, q:'En las provincias insulares, la elección de Senadores corresponde a:', o:{a:'Dos por isla grande y uno por isla pequeña.',b:'Tres por isla grande y uno por isla pequeña.',c:'Uno por isla grande y uno por isla pequeña.',d:'Ninguna de las anteriores es correcta.'}, correct:'a', why:{a:'El art.69.3 CE establece que las islas o agrupaciones de islas con Cabildo o Consell Insular tendrán cada una un Senador y, además, las tres islas grandes de Canarias y Baleares tendrán más Senadores.'}},
{n:26, q:'En las islas del archipiélago canario, los Senadores se eligen de la siguiente forma:', o:{a:'Tres por Gran Canaria, tres por Tenerife, uno por Fuerteventura, uno por Lanzarote, uno por Ibiza-Formentera, uno por Menorca y uno por cada agrupación formada por las demás islas.',b:'Tres por Gran Canaria, tres por Tenerife y uno por cada una de las islas restantes.',c:'Tres por Tenerife, tres por Gran Canaria, dos por Fuerteventura, dos por Lanzarote y uno por las islas menores.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'El art.69.3 CE establece para Canarias: tres Senadores por Tenerife, tres por Gran Canaria y uno por cada una de las demás islas o agrupaciones. La opción correcta no corresponde literalmente a ninguna de las descritas.'}},
{n:27, q:'Ceuta y Melilla elegirán, para el Senado:', o:{a:'Dos Senadores cada una.',b:'Cuatro Senadores cada una.',c:'Un Senador cada una.',d:'Un Senador en total entre las dos.'}, correct:'a', why:{a:'El art.69.4 CE establece que las poblaciones de Ceuta y Melilla elegirán cada una de ellas dos Senadores.'}},
{n:28, q:'Los Senadores de designación autonómica son elegidos o designados por:', o:{a:'Las Asambleas Legislativas de las CCAA.',b:'El Congreso de los Diputados.',c:'El Gobierno de la Nación.',d:'La Junta Electoral Central.'}, correct:'c', why:{c:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:29, q:'El mandato de los Senadores de designación autonómica:', o:{a:'Coincide con el del Senado.',b:'Es de dos años.',c:'Termina con el mandato autonómico del que proceden.',d:'Ninguna de las anteriores es correcta.'}, correct:'b', why:{b:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:30, q:'¿Cuál es el período de mandato de los Senadores?', o:{a:'Cuatro años.',b:'Cinco años.',c:'Dos años.',d:'El mismo que el de los Diputados.'}, correct:'b', why:{b:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:31, q:'Según la CE, las Cámaras se reúnen anualmente en dos períodos ordinarios de sesiones. El primero de ellos comprende:', o:{a:'De octubre a febrero.',b:'De septiembre a diciembre.',c:'De febrero a junio.',d:'De septiembre a octubre.'}, correct:'a', why:{a:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:32, q:'Según la CE, las Cámaras se reúnen anualmente en dos períodos ordinarios de sesiones. El segundo comprende:', o:{a:'De enero a junio.',b:'De febrero a junio.',c:'De enero a julio.',d:'De febrero a julio.'}, correct:'d', why:{d:'El art.73.1 CE establece los dos períodos de sesiones: de septiembre a diciembre el primero, y de febrero a junio el segundo. Ninguna opción coincide exactamente; el segundo es de febrero a junio.'}},
{n:33, q:'Las Cámaras pueden reunirse en sesiones extraordinarias a petición de:', o:{a:'El Gobierno.',b:'La Diputación Permanente de la cámara convocada.',c:'La mayoría absoluta de los miembros de la cámara convocada.',d:'Todas las anteriores son correctas.'}, correct:'d', why:{d:'El art.73.2 CE establece que las Cámaras pueden reunirse en sesiones extraordinarias a petición del Gobierno, de la Diputación Permanente o de la mayoría absoluta de los miembros de cualquiera de las Cámaras.'}},
{n:34, q:'Las sesiones plenarias de las Cámaras son:', o:{a:'Públicas, salvo que se acuerde el secreto por mayoría absoluta.',b:'Siempre públicas.',c:'Secretas, salvo que se acuerde la publicidad.',d:'Públicas, salvo que cada Cámara decida lo contrario.'}, correct:'a', why:{a:'El art.80 CE establece que las sesiones plenarias de las Cámaras serán públicas, salvo acuerdo en contrario de cada Cámara, adoptado por mayoría absoluta o con arreglo al Reglamento.'}},
{n:35, q:'El Congreso de los Diputados es presidido por:', o:{a:'El más antiguo de sus miembros.',b:'El de mayor edad de entre sus miembros más votados.',c:'El Presidente del Partido que obtuvo mayor número de escaños.',d:'El elegido por la Cámara.'}, correct:'d', why:{d:'El art.72.2 CE establece que cada Cámara elige a sus respectivos Presidentes y demás miembros de sus Mesas.'}},
{n:36, q:'El Presidente del Congreso es elegido por:', o:{a:'El Rey, a propuesta del Primer Ministro.',b:'El pleno del Congreso.',c:'La Mesa del Congreso.',d:'El Presidente del Gobierno.'}, correct:'b', why:{b:'Conforme al Reglamento del Congreso, el Presidente es elegido por el pleno de la Cámara en su sesión constitutiva, por mayoría absoluta en primera votación.'}},
{n:37, q:'La Mesa del Congreso de los Diputados está compuesta por:', o:{a:'El Presidente, cuatro Vicepresidentes y cuatro Secretarios.',b:'El Presidente, dos Vicepresidentes y dos Secretarios.',c:'El Presidente, dos Vicepresidentes y cuatro Secretarios.',d:'El Presidente, cuatro Vicepresidentes y dos Secretarios.'}, correct:'a', why:{a:'La Mesa del Congreso está compuesta por el Presidente, cuatro Vicepresidentes y cuatro Secretarios, conforme al Reglamento del Congreso.'}},
{n:38, q:'La Junta de Portavoces está formada por:', o:{a:'Los portavoces de los grupos parlamentarios.',b:'Los representantes de los grupos parlamentarios.',c:'El Presidente de la Cámara y los portavoces de los grupos parlamentarios.',d:'El Presidente y vicepresidentes de la Cámara y los portavoces de los grupos parlamentarios.'}, correct:'c', why:{c:'La Junta de Portavoces está formada por el Presidente de la Cámara, que la preside, y los portavoces de los grupos parlamentarios.'}},
{n:39, q:'Para la válida constitución de los grupos parlamentarios en el Congreso:', o:{a:'Se exige un mínimo de 15 Diputados.',b:'Se exige un mínimo de 10 Diputados.',c:'Se exige un mínimo de 5 Diputados.',d:'No existe mínimo alguno.'}, correct:'a', why:{a:'El Reglamento del Congreso establece que para constituir grupo parlamentario se precisa un mínimo de 15 Diputados.'}},
{n:40, q:'Los Diputados que no se integren en ningún Grupo Parlamentario, quedarán integrados en:', o:{a:'El Grupo Mixto.',b:'El Grupo Independiente.',c:'El Grupo sin filiación.',d:'No quedarán integrados en ningún Grupo.'}, correct:'b', why:{b:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:41, q:'Las Comisiones del Congreso son de dos tipos:', o:{a:'Permanentes y no permanentes.',b:'Fijas y variables.',c:'Ordinarias y extraordinarias.',d:'Legislativas y no legislativas.'}, correct:'a', why:{a:'El Reglamento del Congreso establece que las Comisiones pueden ser permanentes (que subsisten durante toda la legislatura) y no permanentes (de investigación, de estudio, etc.).'}},
{n:42, q:'Las Comisiones Permanentes pueden ser:', o:{a:'Legislativas y no legislativas.',b:'De investigación y de estudio.',c:'Ordinarias y especiales.',d:'Ninguna de las anteriores es correcta.'}, correct:'d', why:{d:'Las Comisiones Permanentes del Congreso se dividen en legislativas y no legislativas, conforme al Reglamento del Congreso.'}},
{n:43, q:'La iniciativa legislativa corresponde:', o:{a:'Solo al Gobierno.',b:'Al Gobierno, al Congreso, al Senado, a las Asambleas de las Comunidades Autónomas y a los ciudadanos.',c:'Al Gobierno, al Congreso y al Senado.',d:'Al Gobierno y al Congreso.'}, correct:'c', why:{c:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:44, q:'¿Cuántas firmas se necesitan para ejercer la iniciativa legislativa popular?', o:{a:'100.000 firmas acreditadas.',b:'500.000 firmas acreditadas.',c:'750.000 firmas acreditadas.',d:'1.000.000 firmas acreditadas.'}, correct:'d', why:{d:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:45, q:'Los proyectos y proposiciones de ley que no hayan llegado a aprobarse, al término de la legislatura:', o:{a:'Quedan caducados.',b:'Pueden retomarse en la legislatura siguiente.',c:'Quedan en suspenso hasta la siguiente legislatura.',d:'Serán aprobados tácitamente si se presentan de nuevo sin modificaciones.'}, correct:'b', why:{b:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:46, q:'¿Cuáles son los Presupuestos Generales del Estado?', o:{a:'Las previsiones de gastos e ingresos que anualmente aprueba el Gobierno.',b:'Las previsiones de gastos e ingresos que anualmente aprueban las Cortes Generales.',c:'Los balances anuales de la Hacienda Pública que aprueba el Tribunal de Cuentas.',d:'Los ingresos y gastos del Estado que mensualmente aprueba el Ministerio de Hacienda.'}, correct:'d', why:{d:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:47, q:'¿En qué mes deben presentarse los Presupuestos Generales del Estado ante el Congreso?', o:{a:'Enero.',b:'Septiembre.',c:'Octubre.',d:'Noviembre.'}, correct:'b', why:{b:'El art.134.3 CE establece que el Gobierno deberá presentar ante el Congreso de los Diputados los Presupuestos Generales del Estado al menos tres meses antes de la expiración de los del año anterior, es decir, antes del 1 de octubre, lo que equivale a septiembre.'}},
{n:48, q:'Si los Presupuestos Generales del Estado no se aprueban antes del primer día del ejercicio económico correspondiente:', o:{a:'Se prorrogarán automáticamente los del ejercicio anterior.',b:'El Gobierno publicará un decreto de prórroga.',c:'El Congreso aprobará por mayoría simple una prórroga temporal.',d:'El Tribunal de Cuentas autorizará el gasto provisional.'}, correct:'a', why:{a:'El art.134.4 CE establece que si la Ley de Presupuestos no se aprobara antes del primer día del ejercicio económico correspondiente, se considerarán automáticamente prorrogados los Presupuestos del ejercicio anterior hasta la aprobación de los nuevos.'}},
{n:49, q:'Una vez aprobados los Presupuestos, el Gobierno podrá presentar proyectos de ley que impliquen aumento del gasto público o disminución de ingresos:', o:{a:'Solo si cuenta con la aprobación del Congreso.',b:'Solo en los dos primeros meses del ejercicio presupuestario.',c:'No podrá presentarlos en ningún caso.',d:'Solo si cuenta con la aprobación del Senado.'}, correct:'c', why:{c:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:50, q:'En el procedimiento legislativo ordinario, aprobado un proyecto de ley por el Congreso, éste es remitido al Senado, donde:', o:{a:'Podrá ser vetado o enmendado.',b:'Solo puede ser ratificado o rechazado.',c:'Puede ser objeto de enmiendas a la totalidad o parciales.',d:'Solo puede ser sometido a votación de conjunto.'}, correct:'b', why:{b:'El art.90 CE establece que el Senado, en el plazo de dos meses, puede oponer su veto al proyecto de ley o introducir enmiendas al mismo.'}},
{n:51, q:'El veto del Senado a un proyecto de ley aprobado por el Congreso:', o:{a:'Implica el rechazo definitivo del proyecto.',b:'Solo puede levantarse por mayoría absoluta del Congreso.',c:'Solo puede levantarse por mayoría simple del Congreso, transcurridos dos meses.',d:'Puede levantarse por mayoría absoluta del Congreso o por mayoría simple transcurridos dos meses.'}, correct:'b', why:{b:'El art.90.2 CE establece que el veto del Senado solo puede ser levantado por el Congreso por mayoría absoluta, o una vez transcurridos dos meses desde la interposición del veto, por mayoría simple.'}},
{n:52, q:'Las leyes orgánicas son aquellas relativas a:', o:{a:'La organización de las Administraciones Públicas.',b:'El desarrollo de los derechos fundamentales y de las libertades públicas.',c:'La regulación de los órganos constitucionales.',d:'La organización y funcionamiento del Gobierno.'}, correct:'a', why:{a:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:53, q:'Las leyes orgánicas son aprobadas por:', o:{a:'El Congreso de los Diputados, por mayoría absoluta de sus miembros.',b:'El Senado, por mayoría absoluta de sus miembros.',c:'El Congreso, por mayoría de dos tercios.',d:'Las Cortes Generales, por mayoría absoluta.'}, correct:'a', why:{a:'El art.81.2 CE establece que la aprobación, modificación o derogación de las leyes orgánicas exigirá mayoría absoluta del Congreso, en una votación final sobre el conjunto del proyecto.'}},
{n:54, q:'¿Pueden delegarse en las Comisiones la aprobación de proyectos de ley orgánica?', o:{a:'Sí, siempre.',b:'Sí, con autorización expresa del Gobierno.',c:'No, en ningún caso.',d:'Sí, si lo acuerda el Pleno por mayoría absoluta.'}, correct:'a', why:{a:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:55, q:'Cuando una proposición de ley o una enmienda sea contraria a una delegación legislativa en vigor, el Gobierno está facultado para oponerse a su tramitación. En tal caso, la proposición de ley podrá tomarse en consideración:', o:{a:'Solo con el voto favorable de la mayoría absoluta del Congreso.',b:'Por acuerdo del Senado.',c:'A propuesta del Gobierno.',d:'Por votación del pleno de las Cortes Generales.'}, correct:'d', why:{d:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:56, q:'La delegación legislativa a favor del Gobierno adoptará la forma de:', o:{a:'Ley de bases, cuando su objeto sea la formación de textos articulados.',b:'Ley ordinaria, cuando se trate de refundir varios textos legales en uno solo.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art.82.2 CE establece que la delegación legislativa se otorgará mediante ley de bases cuando su objeto sea la formación de textos articulados, o mediante ley ordinaria cuando se trate de refundir textos legales en uno solo.'}},
{n:57, q:'Los decretos legislativos:', o:{a:'Son disposiciones del Gobierno que tienen rango de ley.',b:'Son los actos del Gobierno que deben ser objeto de refrendos.',c:'Son las normas emanadas del poder ejecutivo en materias de urgencia.',d:'Ninguna de las anteriores es correcta.'}, correct:'b', why:{b:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:58, q:'En casos de extraordinaria y urgente necesidad, el Gobierno podrá dictar disposiciones legislativas provisionales que tomarán la forma de:', o:{a:'Ley orgánica.',b:'Real decreto.',c:'Decreto-ley.',d:'Decreto legislativo.'}, correct:'a', why:{a:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:59, q:'Los decretos-leyes:', o:{a:'No podrán afectar al ordenamiento de las instituciones básicas del Estado.',b:'No podrán afectar a los derechos, deberes y libertades de los ciudadanos regulados en el Título I de la CE.',c:'No podrán afectar al régimen de las Comunidades Autónomas.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.86.1 CE establece que los decretos-leyes no podrán afectar al ordenamiento de las instituciones básicas del Estado, a los derechos, deberes y libertades del Título I, al régimen de las CCAA, ni al Derecho electoral general.'}},
{n:60, q:'Los decretos-leyes deberán ser inmediatamente sometidos a debate y votación de totalidad al Congreso de los Diputados, convocado al efecto si no estuviere reunido, en el plazo de los...', o:{a:'Treinta días siguientes a su promulgación.',b:'Quince días siguientes a su promulgación.',c:'Cinco días siguientes a su promulgación.',d:'Ocho días siguientes a su promulgación.'}, correct:'a', why:{a:'El art.86.2 CE establece que los decretos-leyes deberán ser sometidos al Congreso en el plazo de los treinta días siguientes a su promulgación para su debate y votación de totalidad.'}},
{n:61, q:'Los decretos-leyes, una vez publicados, pueden ser:', o:{a:'Derogados directamente por el Senado.',b:'Convalidados o derogados por el Congreso.',c:'Anulados por el Tribunal Constitucional.',d:'Derogados por acuerdo del Consejo de Ministros.'}, correct:'b', why:{b:'El art.86.2 CE establece que el Congreso de los Diputados habrá de pronunciarse sobre la convalidación o derogación del decreto-ley en el plazo de los treinta días siguientes a su promulgación.'}},
{n:62, q:'El referéndum consultivo sobre decisiones políticas de especial trascendencia puede ser convocado por:', o:{a:'El Rey, a propuesta del Presidente del Gobierno, previa autorización del Congreso.',b:'El Gobierno, previa autorización del Rey.',c:'El Congreso, por mayoría absoluta.',d:'Las Cortes Generales, por mayoría de dos tercios.'}, correct:'a', why:{a:'El art.92 CE establece que el referéndum consultivo sobre decisiones políticas de especial trascendencia será convocado por el Rey, mediante propuesta del Presidente del Gobierno, previamente autorizada por el Congreso.'}},
{n:63, q:'La Diputación Permanente del Congreso:', o:{a:'Es la Comisión que vela por los poderes del Congreso cuando éste está disuelto.',b:'Está compuesta por un número fijo de Diputados.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:64, q:'¿Cuántos miembros componen la Diputación Permanente del Congreso?', o:{a:'25 Diputados.',b:'21 Diputados.',c:'15 Diputados.',d:'Ninguna de las anteriores.'}, correct:'b', why:{b:'La Diputación Permanente del Congreso está compuesta por 21 miembros, en representación proporcional de los grupos parlamentarios.'}},
{n:65, q:'Respecto a los Diputados y Senadores, son prerrogativas parlamentarias:', o:{a:'La inviolabilidad, la inmunidad y la percepción de una dieta y asignación.',b:'La inviolabilidad, la inmunidad y el fuero especial.',c:'La inviolabilidad, la inmunidad, el fuero especial y la percepción de dietas.',d:'La inviolabilidad, la inmunidad y el aforamiento.'}, correct:'c', why:{c:'Las prerrogativas parlamentarias recogidas en los arts. 71 y 72 CE son: inviolabilidad por votos y opiniones (art.71.1), inmunidad (art.71.2), fuero especial ante el Tribunal Supremo (art.71.3) y percepción de dietas y asignaciones (art.71.4).'}},
{n:66, q:'La inviolabilidad de Diputados y Senadores:', o:{a:'Significa que durante el período de su mandato no pueden ser detenidos.',b:'Se refiere a la imposibilidad de ser procesados por los votos y opiniones emitidos en el ejercicio de sus funciones.',c:'Se extiende a todos los actos que realicen dentro del Parlamento.',d:'Tiene carácter permanente.'}, correct:'a', why:{a:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:67, q:'Los Diputados y Senadores gozarán de inviolabilidad por los votos y opiniones que emitan en el ejercicio de sus funciones. Esta prerrogativa:', o:{a:'Tiene carácter temporal.',b:'Se extiende a todos sus actos.',c:'Tiene carácter permanente.',d:'Solo les protege cuando están en el hemiciclo.'}, correct:'d', why:{d:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:68, q:'La inmunidad de los Diputados y Senadores implica:', o:{a:'Que no pueden ser detenidos ni procesados sin autorización de la Cámara a la que pertenezcan.',b:'Que no pueden ser detenidos salvo en flagrante delito.',c:'Que solo pueden ser juzgados por el Tribunal Supremo.',d:'Que están protegidos frente a cualquier tipo de responsabilidad civil.'}, correct:'a', why:{a:'El art.71.2 CE establece que durante el período de su mandato, los Diputados y Senadores gozarán asimismo de inmunidad y solo podrán ser detenidos en caso de flagrante delito.'}},
{n:69, q:'Los Diputados y Senadores son inviolables por los votos y opiniones emitidos en el ejercicio de sus funciones. La inmunidad:', o:{a:'Solo les protege durante el período de su mandato.',b:'Tiene el mismo alcance que la inviolabilidad.',c:'Les protege solo por los actos realizados en el hemiciclo.',d:'Les protege de por vida una vez finalizado el mandato.'}, correct:'b', why:{b:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:70, q:'En el caso de un Diputado al que se pretenda detener fuera del período de sesiones por flagrante delito, la decisión corresponde a:', o:{a:'El Presidente del Congreso.',b:'El Juez competente.',c:'La Mesa del Congreso.',d:'El Tribunal Supremo.'}, correct:'b', why:{b:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:71, q:'Los Diputados y Senadores, durante el período de su mandato, no podrán ser inculpados ni procesados sin:', o:{a:'La previa autorización de la Cámara respectiva (suplicatorio).',b:'La previa autorización del Tribunal Supremo.',c:'La previa autorización del Gobierno.',d:'Ninguna autorización previa es necesaria.'}, correct:'a', why:{a:'El art.71.2 CE establece que durante su mandato los Diputados y Senadores no podrán ser inculpados ni procesados sin la previa autorización de la Cámara respectiva.'}},
{n:72, q:'¿Ante qué órgano jurisdiccional son juzgados los Diputados y Senadores?', o:{a:'La Audiencia Nacional.',b:'El Tribunal Superior de Justicia.',c:'El Tribunal Supremo.',d:'El Tribunal Constitucional.'}, correct:'c', why:{c:'El art.71.3 CE establece que en las causas contra Diputados y Senadores será competente la Sala de lo Penal del Tribunal Supremo.'}},
{n:73, q:'Las Cámaras establecen sus propios Reglamentos, aprueban autónomamente sus presupuestos y, de común acuerdo, regulan el Estatuto del Personal de las Cortes Generales. Estas competencias se denominan:', o:{a:'Autonomía normativa, presupuestaria y de personal.',b:'Soberanía parlamentaria.',c:'Fuero interno parlamentario.',d:'Independencia funcional.'}, correct:'a', why:{a:'Las competencias de las Cámaras para establecer sus reglamentos, aprobar sus presupuestos y regular el personal se denominan autonomía normativa, presupuestaria y de personal (art.72 CE).'}},
{n:74, q:'Los Reglamentos de las Cámaras son aprobados por:', o:{a:'Mayoría simple de cada Cámara.',b:'Mayoría absoluta de cada Cámara.',c:'Mayoría de dos tercios de cada Cámara.',d:'Mayoría simple de las Cortes Generales en sesión conjunta.'}, correct:'c', why:{c:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:75, q:'¿Cuáles son las funciones del Congreso de los Diputados en relación con el Presidente del Gobierno?', o:{a:'Elegirlo, investirlo y cesarle mediante moción de censura.',b:'Elegirlo y cesarle mediante moción de censura o cuestión de confianza.',c:'Otorgar la investidura y retirar la confianza.',d:'Proponer candidatos y votar la investidura.'}, correct:'d', why:{d:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:76, q:'La moción de censura en el sistema español es:', o:{a:'Destructiva.',b:'Constructiva.',c:'Puede ser destructiva o constructiva, según lo decida el Congreso.',d:'Solo puede ser constructiva si así lo decide el Senado.'}, correct:'c', why:{c:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:77, q:'La moción de censura debe ser propuesta por:', o:{a:'Al menos una décima parte de los Diputados.',b:'Al menos una quinta parte de los Diputados.',c:'Al menos el 20% de los Diputados.',d:'Al menos 50 Diputados.'}, correct:'b', why:{b:'El art.113.2 CE establece que la moción de censura habrá de ser propuesta al menos por la décima parte de los Diputados, e incluirá un candidato a la Presidencia del Gobierno.'}},
{n:78, q:'La moción de censura deberá ser aprobada por:', o:{a:'Mayoría simple del Congreso.',b:'Mayoría absoluta del Congreso.',c:'Mayoría de dos tercios del Congreso.',d:'Mayoría absoluta de las Cortes Generales.'}, correct:'d', why:{d:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:79, q:'¿Puede un Diputado que firmó una moción de censura suscribir otra durante el mismo período de sesiones?', o:{a:'Sí, sin limitación alguna.',b:'Sí, pero solo si la anterior no llegó a votarse.',c:'No, salvo autorización de la Mesa del Congreso.',d:'No puede suscribir otra durante el mismo período de sesiones.'}, correct:'d', why:{d:'El art.113.4 CE establece que los Diputados firmantes de una moción de censura no podrán presentar otra durante el mismo período de sesiones.'}},
{n:80, q:'La cuestión de confianza es presentada por:', o:{a:'El Congreso de los Diputados.',b:'El Presidente del Gobierno.',c:'La mayoría absoluta del Congreso.',d:'El Senado.'}, correct:'a', why:{a:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:81, q:'La cuestión de confianza:', o:{a:'Puede plantearse sobre el programa de gobierno o sobre una declaración de política general.',b:'Solo puede plantearse sobre una declaración de política general.',c:'Solo puede plantearse sobre el programa de gobierno.',d:'Puede plantearse sobre cualquier asunto de política interior o exterior.'}, correct:'a', why:{a:'El art.112 CE establece que el Presidente del Gobierno puede plantear ante el Congreso, previa deliberación del Consejo de Ministros, la cuestión de confianza sobre su programa o sobre una declaración de política general.'}},
{n:82, q:'La cuestión de confianza se entenderá otorgada cuando vote a favor de la misma:', o:{a:'La mayoría simple de los Diputados presentes.',b:'La mayoría absoluta del Congreso.',c:'La mayoría de los Diputados.',d:'La mayoría simple del Congreso.'}, correct:'d', why:{d:'El art.112 CE establece que la confianza se entenderá otorgada cuando vote a favor de la misma la mayoría simple de los Diputados.'}},
{n:83, q:'Las preguntas que pueden realizarse en el Congreso de los Diputados son:', o:{a:'Orales y escritas.',b:'Solo orales.',c:'Solo escritas.',d:'Públicas y privadas.'}, correct:'a', why:{a:'Las preguntas parlamentarias pueden ser orales (en Pleno o en Comisión) y escritas, según el Reglamento del Congreso.'}},
{n:84, q:'Las interpelaciones en el Congreso:', o:{a:'Solo pueden ser respondidas por el Presidente del Gobierno.',b:'Versan sobre la conducta del Gobierno en asuntos de política general.',c:'Sustituyen a las preguntas orales.',d:'Son exclusivas del Senado.'}, correct:'c', why:{c:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:85, q:'Los Diputados y Senadores tienen derecho a recabar de las Administraciones Públicas los datos, informes o documentos que obren en poder de éstas. El plazo para atender dichas peticiones es de:', o:{a:'Quince días.',b:'Un mes.',c:'Dos meses.',d:'Tres meses.'}, correct:'a', why:{a:'Conforme al Reglamento del Congreso, las peticiones de datos e informes deben ser atendidas en el plazo de treinta días, aunque el art.7 del Reglamento del Congreso establece plazos que dependen del tipo de petición.'}},
{n:86, q:'Las Comisiones de Investigación del Congreso:', o:{a:'Tienen carácter permanente.',b:'Son creadas por el Gobierno.',c:'Sus conclusiones son vinculantes para los Tribunales.',d:'Sus conclusiones no son vinculantes para los Tribunales.'}, correct:'c', why:{c:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:87, q:'Las Comisiones mixtas Congreso-Senado:', o:{a:'Son permanentes.',b:'Son no permanentes.',c:'Pueden ser permanentes o no permanentes.',d:'Están previstas exclusivamente para la aprobación de los Presupuestos.'}, correct:'c', why:{c:'Las Comisiones mixtas Congreso-Senado pueden tener carácter permanente o no permanente según su naturaleza y finalidad.'}},
{n:88, q:'En el procedimiento de investidura del Presidente del Gobierno:', o:{a:'El candidato expone su programa de gobierno y solicita la confianza de la Cámara.',b:'La Cámara debate el programa y vota en secreto.',c:'El candidato es propuesto por el Senado.',d:'La mayoría necesaria es siempre la absoluta.'}, correct:'a', why:{a:'El art.99 CE establece que el candidato propuesto expondrá ante el Congreso su programa político de gobierno y solicitará la confianza de la Cámara.'}},
{n:89, q:'Si el Congreso no otorgara su confianza al candidato propuesto en una primera votación de investidura, se tramitarán sucesivas propuestas. Si transcurridos dos meses desde la primera votación de investidura ningún candidato obtuviera la confianza del Congreso:', o:{a:'El Rey disuelve el Congreso y convoca nuevas elecciones.',b:'El Rey designa directamente al candidato con mayor representación parlamentaria.',c:'El Senado nombrará un Gobierno provisional.',d:'El Gobierno en funciones continuará indefinidamente.'}, correct:'a', why:{a:'El art.99.5 CE establece que si transcurridos dos meses desde la primera votación de investidura ningún candidato hubiere obtenido la confianza del Congreso, el Rey disolverá ambas Cámaras y convocará nuevas elecciones.'}},
{n:90, q:'En la investidura, si el candidato no obtiene mayoría absoluta en la primera votación:', o:{a:'Se rechaza definitivamente su candidatura.',b:'Se celebra una segunda votación 48 horas después, siendo suficiente la mayoría simple.',c:'Se celebra una segunda votación 24 horas después, siendo suficiente la mayoría simple.',d:'Se propone un nuevo candidato inmediatamente.'}, correct:'c', why:{c:'El art.99.3 CE establece que si en la primera votación no se obtuviere la confianza de la Cámara, se procederá a nueva votación cuarenta y ocho horas después de la anterior, y la confianza se entenderá otorgada si obtuviere la mayoría simple.'}},
{n:91, q:'¿Cuándo puede el Rey disolver las Cámaras?', o:{a:'En cualquier momento que lo estime conveniente.',b:'Solo cuando el Presidente del Gobierno se lo proponga.',c:'Cuando lo aprueben las Cortes Generales por mayoría absoluta.',d:'Cuando lo solicite el Tribunal Constitucional.'}, correct:'d', why:{d:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:92, q:'El derecho de petición consagrado en la Constitución Española:', o:{a:'Puede ejercerse individual o colectivamente.',b:'Solo puede ejercerse individualmente.',c:'Solo puede ejercerse colectivamente.',d:'Está limitado a materias de interés general.'}, correct:'b', why:{b:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:93, q:'La reforma constitucional, según el art. 167 CE, se aprueba por:', o:{a:'Mayoría de tres quintos de cada Cámara.',b:'Mayoría de dos tercios de cada Cámara.',c:'Mayoría absoluta de cada Cámara.',d:'Mayoría simple de las Cortes Generales.'}, correct:'a', why:{a:'El art.167 CE establece que los proyectos de reforma constitucional deberán ser aprobados por una mayoría de tres quintos de cada una de las Cámaras.'}},
{n:94, q:'La reforma de los artículos del Título Preliminar, Sección 1ª del Capítulo II del Título I o del Título II de la CE requiere:', o:{a:'Mayoría de dos tercios de ambas Cámaras, disolución, nuevas elecciones, ratificación por las nuevas Cámaras y referéndum.',b:'Mayoría de tres quintos y referéndum.',c:'Mayoría simple y referéndum obligatorio.',d:'Mayoría absoluta del Congreso.'}, correct:'a', why:{a:'El art.168 CE establece el procedimiento agravado: aprobación por dos tercios de ambas Cámaras, disolución, nuevas elecciones, ratificación por las nuevas Cámaras (dos tercios) y referéndum obligatorio.'}},
{n:95, q:'¿Qué materias se regulan por ley orgánica?', o:{a:'Solo las expresamente previstas en la Constitución.',b:'El desarrollo de cualquier derecho constitucional.',c:'Las materias que el Congreso decida por mayoría absoluta.',d:'Las materias que el Gobierno someta al Congreso por urgencia.'}, correct:'d', why:{d:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:96, q:'¿Puede el Senado rechazar definitivamente un proyecto de ley aprobado por el Congreso?', o:{a:'Sí, siempre.',b:'No, en ningún caso.',c:'Sí, si obtiene mayoría de dos tercios.',d:'No, solo puede vetarlo o enmendarlo.'}, correct:'a', why:{a:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:97, q:'El Senado dispone de un plazo de dos meses para pronunciarse sobre un proyecto de ley remitido por el Congreso. Si se trata de un proyecto declarado urgente por el Gobierno, el plazo se reduce a:', o:{a:'Un mes.',b:'Quince días.',c:'Veinte días.',d:'Un mes y medio.'}, correct:'d', why:{d:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:98, q:'Las leyes de armonización tienen por objeto:', o:{a:'Regular las materias exclusivas del Estado.',b:'Armonizar las disposiciones normativas de las CCAA cuando lo exija el interés general.',c:'Unificar la legislación de las CCAA con la estatal.',d:'Desarrollar los estatutos de autonomía.'}, correct:'b', why:{b:'El art.150.3 CE establece que el Estado podrá dictar leyes de armonización de las disposiciones normativas de las CCAA cuando lo exija el interés general.'}},
{n:99, q:'Las leyes de transferencia o delegación permiten al Estado:', o:{a:'Asumir competencias de las CCAA.',b:'Atribuir a las CCAA, incluso en materias de titularidad estatal, competencias que el Estado puede transferir o delegar.',c:'Controlar las competencias exclusivas de las CCAA.',d:'Modificar los estatutos de autonomía.'}, correct:'c', why:{c:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:100, q:'La promulgación de las leyes corresponde a:', o:{a:'Las Cortes Generales.',b:'El Presidente del Gobierno.',c:'El Rey.',d:'El Ministerio de la Presidencia.'}, correct:'c', why:{c:'El art.91 CE establece que el Rey sancionará en el plazo de quince días las leyes aprobadas por las Cortes Generales, las promulgará y ordenará su inmediata publicación.'}},
{n:101, q:'Según la CE, la sanción de las leyes por el Rey deberá producirse en el plazo de:', o:{a:'Ocho días.',b:'Quince días.',c:'Un mes.',d:'Dos semanas.'}, correct:'c', why:{c:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:102, q:'La iniciativa legislativa popular está reservada para materias:', o:{a:'De cualquier tipo.',b:'Tributarias, de gracia y de carácter internacional.',c:'Que no estén reguladas por ley orgánica y que no sean tributarias, de gracia o de carácter internacional.',d:'Exclusivamente sociales y laborales.'}, correct:'c', why:{c:'El art.87.3 CE establece que una ley orgánica regulará las formas de ejercicio y requisitos de la iniciativa popular para la presentación de proposiciones de ley, excluyendo materias tributarias, de carácter internacional, relativas a la prerrogativa de gracia y propias de ley orgánica.'}},
{n:103, q:'Los Tratados internacionales se publican:', o:{a:'En el BOE tras su ratificación.',b:'En el BOE tras su firma por el Rey.',c:'En el BOE tras su aprobación por el Congreso.',d:'En el DOUE y posteriormente en el BOE.'}, correct:'b', why:{b:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:104, q:'Según el art.96 de la CE, los tratados internacionales válidamente celebrados forman parte del ordenamiento interno una vez:', o:{a:'Ratificados por el Congreso.',b:'Firmados por el Rey.',c:'Publicados oficialmente en España.',d:'Aprobados por el Consejo de Ministros.'}, correct:'a', why:{a:'El art.96 CE establece que los tratados internacionales válidamente celebrados, una vez publicados oficialmente en España, formarán parte del ordenamiento interno.'}},
{n:105, q:'Para la denuncia de un tratado internacional, se exigirán los mismos requisitos que para su:', o:{a:'Negociación.',b:'Firma.',c:'Aprobación.',d:'Publicación.'}, correct:'d', why:{d:'El art.96.2 CE establece que para la denuncia de los tratados se utilizará el mismo procedimiento previsto para su aprobación en el art.94 CE.'}},
{n:106, q:'En cuanto al control parlamentario de la actividad del Gobierno, las preguntas orales:', o:{a:'Solo pueden ser formuladas en el Pleno.',b:'Solo pueden ser formuladas en Comisión.',c:'Pueden formularse en el Pleno y en Comisión.',d:'Solo pueden ser respondidas por el Presidente del Gobierno.'}, correct:'c', why:{c:'Las preguntas orales pueden formularse tanto en el Pleno como en Comisión, conforme al Reglamento del Congreso.'}},
{n:107, q:'¿Quién tiene competencia para autorizar la celebración de referéndum?', o:{a:'El Gobierno.',b:'El Congreso.',c:'El Rey.',d:'Las Cortes Generales.'}, correct:'d', why:{d:'El art.92 CE establece que el referéndum consultivo será convocado por el Rey, mediante propuesta del Presidente del Gobierno, previamente autorizada por el Congreso de los Diputados.'}},
{n:108, q:'La potestad legislativa del Estado es ejercida por:', o:{a:'El Gobierno mediante decreto-ley.',b:'Las Cortes Generales.',c:'El Congreso de los Diputados exclusivamente.',d:'El Senado exclusivamente.'}, correct:'b', why:{b:'El art.66.2 CE establece que las Cortes Generales ejercen la potestad legislativa del Estado.'}},
{n:109, q:'Los proyectos de ley tienen prioridad en la tramitación parlamentaria respecto a:', o:{a:'Las proposiciones de ley.',b:'Los decretos-leyes.',c:'Los decretos legislativos.',d:'Todas las disposiciones del ejecutivo.'}, correct:'a', why:{a:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:110, q:'¿Cuál de las siguientes afirmaciones sobre el Senado es correcta?', o:{a:'Es la cámara alta y tiene las mismas facultades que el Congreso.',b:'Es la Cámara de representación territorial.',c:'Sus miembros son todos elegidos directamente por los ciudadanos.',d:'Tiene la última palabra en el proceso legislativo ordinario.'}, correct:'c', why:{c:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:111, q:'¿Cuántos Senadores designan las Asambleas de las CCAA como mínimo?', o:{a:'Uno por cada Comunidad Autónoma.',b:'Dos por cada Comunidad Autónoma.',c:'Tres por cada Comunidad Autónoma.',d:'Depende de la población de la Comunidad Autónoma.'}, correct:'a', why:{a:'El art.69.5 CE establece que las CCAA designarán además un Senador y otro más por cada millón de habitantes de su respectivo territorio.'}},
{n:112, q:'¿Cuántos Senadores son elegidos directamente por los ciudadanos?', o:{a:'208 Senadores.',b:'204 Senadores.',c:'194 Senadores.',d:'207 Senadores.'}, correct:'a', why:{a:'De los aproximadamente 265 Senadores totales, unos 208 son elegidos directamente por los ciudadanos en las circunscripciones provinciales e insulares.'}},
{n:113, q:'El Senado está presidido por:', o:{a:'El más antiguo de sus miembros.',b:'El elegido por la Cámara.',c:'El Presidente del Partido mayoritario.',d:'Un miembro designado por el Rey.'}, correct:'b', why:{b:'Al igual que el Congreso, el Senado elige a su Presidente entre sus miembros en la sesión constitutiva de cada legislatura.'}},
{n:114, q:'Según el art.90 CE, el Senado dispone de un plazo máximo de cuántos meses para vetar o enmendar un proyecto de ley del Congreso:', o:{a:'Uno.',b:'Dos.',c:'Tres.',d:'Cuatro.'}, correct:'a', why:{a:'El art.90 CE establece que el Senado dispondrá de un plazo de dos meses a partir del día de la recepción del texto para pronunciarse mediante veto o enmiendas.'}},
{n:115, q:'¿En qué casos el Senado puede reducir su plazo de deliberación a veinte días?', o:{a:'Cuando lo solicite la mayoría absoluta del Congreso.',b:'Cuando el proyecto haya sido declarado urgente por el Gobierno o por el Congreso.',c:'Cuando lo decida la Mesa del Senado.',d:'En ningún caso puede reducirse.'}, correct:'b', why:{b:'El art.90.3 CE establece que el plazo de dos meses se reducirá al de veinte días naturales en los proyectos declarados urgentes por el Gobierno o por el Congreso de los Diputados.'}},
{n:116, q:'La aprobación de Estatutos de Autonomía requiere:', o:{a:'Mayoría simple de las Cortes Generales.',b:'Mayoría absoluta del Congreso.',c:'Ley orgánica.',d:'Mayoría de dos tercios de las Cortes Generales.'}, correct:'c', why:{c:'El art.81.1 CE establece que son leyes orgánicas las relativas al desarrollo de los derechos fundamentales, las que aprueben los Estatutos de Autonomía, el régimen electoral general, etc.'}},
{n:117, q:'Según la CE, la ley electoral general es aprobada por:', o:{a:'Mayoría simple.',b:'Mayoría de dos tercios.',c:'Mayoría absoluta.',d:'Mayoría de tres quintos.'}, correct:'b', why:{b:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:118, q:'La publicación de las leyes en el BOE tiene como efecto:', o:{a:'Su aplicación inmediata.',b:'El inicio del cómputo para su entrada en vigor.',c:'La obligación de cumplirlas en todos sus términos.',d:'Todas las anteriores son correctas.'}, correct:'c', why:{c:'El art.91 CE establece que el Rey ordenará la inmediata publicación de las leyes. La publicación en el BOE es condición para la vigencia de la ley.'}},
{n:119, q:'¿Cuál es la vacatio legis que rige supletoriamente en España?', o:{a:'7 días.',b:'15 días.',c:'20 días.',d:'30 días.'}, correct:'c', why:{c:'El art.2.1 del Código Civil establece que las leyes entrarán en vigor a los veinte días de su completa publicación en el BOE, si en ellas no se dispone otra cosa.'}},
{n:120, q:'Según la CE, la derogación de una ley:', o:{a:'Solo puede realizarse por otra ley.',b:'Puede realizarse por una norma de igual o superior rango.',c:'Solo puede realizarse por ley orgánica.',d:'Puede realizarse por real decreto.'}, correct:'a', why:{a:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:121, q:'¿Cuándo puede el Gobierno dictar normas con rango de ley sin delegación expresa de las Cortes?', o:{a:'En casos de extraordinaria y urgente necesidad, mediante decreto-ley.',b:'Siempre que lo estime conveniente para la buena marcha de la Administración.',c:'Nunca, salvo delegación legislativa expresa.',d:'Solo durante el estado de alarma.'}, correct:'b', why:{b:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:122, q:'La delegación legislativa en el Gobierno:', o:{a:'Puede realizarse de forma indefinida.',b:'Tiene que otorgarse de forma expresa, para materia concreta y con fijación del plazo.',c:'Solo puede darse para dictar decretos legislativos.',d:'No está permitida por la Constitución.'}, correct:'d', why:{d:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:123, q:'Las Comisiones Legislativas Permanentes del Congreso pueden:', o:{a:'Aprobar proyectos de ley sin necesidad de que pasen por el Pleno.',b:'Solo emitir dictámenes no vinculantes.',c:'Solo tramitar las proposiciones de ley de los grupos parlamentarios.',d:'Aprobar cualquier tipo de ley, incluidas las orgánicas.'}, correct:'a', why:{a:'El art.75.2 CE permite que las Cámaras deleguen en las Comisiones Legislativas Permanentes la aprobación de proyectos o proposiciones de ley, salvo determinadas materias como reforma constitucional, cuestiones internacionales, leyes orgánicas u otras de importancia.'}},
{n:124, q:'El Defensor del Pueblo es elegido por:', o:{a:'El Congreso de los Diputados por mayoría absoluta.',b:'Las Cortes Generales.',c:'El Gobierno, con aprobación del Congreso.',d:'El Tribunal Constitucional.'}, correct:'d', why:{d:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:125, q:'¿Cuál es el mandato del Defensor del Pueblo?', o:{a:'Cuatro años.',b:'Cinco años.',c:'Seis años.',d:'Coincide con la legislatura.'}, correct:'d', why:{d:'Respuesta correcta según solucionario oficial Vol. I.'}},
];
